// Package nexaicons exposes the Nexa Icons set: 650 stroke-only SVG icons drawn
// on a 24x24 grid and derived from Lucide 1.70 (ISC).
//
// Geometry, names, aliases, keywords and animation presets come from
// data/icons.json; swap pairs come from data/swaps.json. The icon and swap
// tables in icons_gen.go are generated by scripts/generate-go.mjs; this file is
// the hand-written API.
//
// The rendered markup (attribute set, order and values) matches the JavaScript
// reference implementation in js/index.mjs so the same icon produced by any
// Nexa package is structurally identical.
//
// Quick start:
//
//	icon, ok := nexaicons.Get("bell") // case-insensitive, alias/kebab aware
//	if ok {
//		fmt.Println(icon.SVG(nexaicons.Size(20), nexaicons.Label("Alerts")))
//	}
//	fmt.Println(nexaicons.Sprite()) // inline once, reference with <use href="#nexa-bell">
package nexaicons

import (
	"sort"
	"strconv"
	"strings"
)

// Icon is one icon definition from data/icons.json.
//
// Name is the canonical PascalCase name, Kebab the URL/file-safe form,
// Preset and Trigger the semantic animation defaults, Aliases the accepted
// alternative names (including Name itself), Keywords the search terms, and
// Inner the ready-to-embed SVG child markup.
type Icon struct {
	Name     string
	Kebab    string
	Preset   string
	Trigger  string
	Aliases  []string
	Keywords []string
	Inner    string
}

// Icons maps every canonical icon name to its definition.
//
// Use Get instead of indexing this map directly: Get resolves aliases and is
// case-insensitive. The map is built once at package initialisation.
var Icons = func() map[string]Icon {
	icons := make(map[string]Icon, len(generatedIcons))
	for _, icon := range generatedIcons {
		icons[icon.Name] = icon
	}
	return icons
}()

// compactKey normalizes a lookup query the same way the JavaScript packages do
// (js/index.mjs `compact()`): lower-case, then strip every space, underscore or
// hyphen. This makes "TriangleAlert", "Triangle Alert", "triangle_alert" and
// "Alert-Triangle" all resolve, while staying deterministic.
func compactKey(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	var b strings.Builder
	b.Grow(len(value))
	for _, r := range value {
		switch r {
		case ' ', '\t', '\n', '\r', '_', '-':
			continue
		}
		b.WriteRune(r)
	}
	return b.String()
}

// canonicalByKey maps compacted names, kebabs and aliases to the canonical
// name. Data order wins if two icons ever claim the same key (the generator
// rejects such datasets, so this is only a defensive guarantee).
var canonicalByKey = func() map[string]string {
	index := make(map[string]string, len(generatedIcons)*2)
	indexKey := func(key, canonical string) {
		key = compactKey(key)
		if key == "" {
			return
		}
		if _, exists := index[key]; !exists {
			index[key] = canonical
		}
	}
	for _, icon := range generatedIcons {
		indexKey(icon.Name, icon.Name)
		indexKey(icon.Kebab, icon.Name)
		for _, alias := range icon.Aliases {
			indexKey(alias, icon.Name)
		}
	}
	return index
}()

// lookupCanonical resolves a name, alias or kebab-case name to the canonical
// icon name using the shared compact normalization.
func lookupCanonical(name string) (string, bool) {
	key := compactKey(name)
	if key == "" {
		return "", false
	}
	canonical, ok := canonicalByKey[key]
	return canonical, ok
}

// Get looks up an icon by canonical name, alias, or kebab-case name. The
// lookup is case-insensitive, ignores surrounding whitespace, and strips
// spaces/underscores/hyphens between words.
func Get(name string) (Icon, bool) {
	canonical, ok := lookupCanonical(name)
	if !ok {
		return Icon{}, false
	}
	icon, ok := Icons[canonical]
	return icon, ok
}

// Names returns every canonical icon name in lexicographic order. The result
// is a fresh slice on every call; callers may sort or modify it freely.
func Names() []string {
	names := make([]string, len(generatedIcons))
	for i, icon := range generatedIcons {
		names[i] = icon.Name
	}
	sort.Strings(names)
	return names
}

// ---------------------------------------------------------------------------
// Symbols and sprite.
// ---------------------------------------------------------------------------

const spriteOpen = `<svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" style="display:none">`

// symbolOpen is everything between the symbol id and its child markup.
const symbolOpen = `" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="`
const symbolClose = `" stroke-linecap="round" stroke-linejoin="round">`

// symbolMarkup renders one sprite <symbol>. The sprite is a definition
// container, so its stroke weight is fixed at the requested value (2 by
// default) rather than derived from a rendered size.
func symbolMarkup(icon Icon, strokeWidth float64) string {
	var b strings.Builder
	b.Grow(len(icon.Kebab) + len(icon.Inner) + 160)
	b.WriteString(`<symbol id="nexa-`)
	b.WriteString(icon.Kebab)
	b.WriteString(symbolOpen)
	b.WriteString(formatNumber(strokeWidth))
	b.WriteString(symbolClose)
	b.WriteString(icon.Inner)
	b.WriteString(`</symbol>`)
	return b.String()
}

// SymbolOption customises Symbol.
type SymbolOption func(*symbolConfig)

type symbolConfig struct {
	strokeWidth float64
}

// SymbolStrokeWidth sets the symbol's stroke-width (default 2).
func SymbolStrokeWidth(width float64) SymbolOption {
	return func(c *symbolConfig) {
		if width > 0 && width < 1e6 {
			c.strokeWidth = width
		}
	}
}

// Symbol renders a single icon as an SVG <symbol> for embedding in an existing
// sprite, matching JS symbol(name, { strokeWidth }) and Rust Icon::symbol():
//
//	<symbol id="nexa-bell" viewBox="0 0 24 24" fill="none" stroke="currentColor"
//	        stroke-width="2" stroke-linecap="round" stroke-linejoin="round">…</symbol>
//
// The default stroke width is 2 (sprite contract); override it with
// SymbolStrokeWidth. The bool is false for unknown icons.
func Symbol(name string, opts ...SymbolOption) (string, bool) {
	icon, ok := Get(name)
	if !ok {
		return "", false
	}
	cfg := symbolConfig{strokeWidth: 2}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}
	return symbolMarkup(icon, cfg.strokeWidth), true
}

// SpriteOption customises Sprite.
type SpriteOption func(*spriteConfig)

type spriteConfig struct {
	strokeWidth float64
}

// SpriteStrokeWidth sets the stroke-width of every symbol (default 2).
func SpriteStrokeWidth(width float64) SpriteOption {
	return func(c *spriteConfig) {
		if width > 0 && width < 1e6 {
			c.strokeWidth = width
		}
	}
}

// Sprite renders all 650 icons as a single inline SVG sprite:
//
//	<svg ...><symbol id="nexa-bell" viewBox="0 0 24 24" ...>...</symbol>...</svg>
//
// Inline it once per page and reference symbols with
// `<svg class="nexa-icon"><use href="#nexa-bell"/></svg>`. Sprite symbols use a
// fixed stroke width of 2 by default (matching the canonical sprite.svg and
// JS sprite()); use SpriteStrokeWidth to change it. Inline icons rendered by
// Icon.SVG are size-aware instead.
func Sprite(opts ...SpriteOption) string {
	cfg := spriteConfig{strokeWidth: 2}
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}
	capacity := len(spriteOpen) + len(`</svg>`)
	for _, icon := range generatedIcons {
		capacity += len(icon.Kebab) + len(icon.Inner) + 160
	}
	var b strings.Builder
	b.Grow(capacity)
	b.WriteString(spriteOpen)
	for _, icon := range generatedIcons {
		b.WriteString(symbolMarkup(icon, cfg.strokeWidth))
	}
	b.WriteString(`</svg>`)
	return b.String()
}

// ---------------------------------------------------------------------------
// Inline SVG renderer.
// ---------------------------------------------------------------------------

// strokeForSize is the Nexa size→stroke rule: stroke gets optically lighter as
// the icon grows. 16px => 2, 20px => 1.75, 24px and up => 1.5.
func strokeForSize(px int) float64 {
	switch {
	case px <= 16:
		return 2
	case px <= 20:
		return 1.75
	default:
		return 1.5
	}
}

// formatNumber formats a stroke width the way JavaScript's Number#toString
// does for the values we accept (2 => "2", 1.75 => "1.75").
func formatNumber(value float64) string {
	return strconv.FormatFloat(value, 'g', -1, 64)
}

// escapeAttr escapes an attribute/text value exactly like js/index.mjs esc():
// &, <, >, " and ' become XML entities.
func escapeAttr(value string) string {
	var b strings.Builder
	b.Grow(len(value))
	for _, r := range value {
		switch r {
		case '&':
			b.WriteString("&amp;")
		case '<':
			b.WriteString("&lt;")
		case '>':
			b.WriteString("&gt;")
		case '"':
			b.WriteString("&quot;")
		case '\'':
			b.WriteString("&#39;")
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// svgConfig is the resolved option state for one SVG render.
type svgConfig struct {
	size        int
	strokeWidth float64
	strokeSet   bool
	class       string
	label       string
	title       string
	anim        string
	trigger     string
	active      bool
}

func defaultSVGConfig() svgConfig {
	return svgConfig{size: 24}
}

// Option customises Icon.SVG. Options are applied in order; a zero or negative
// size or stroke width is ignored so defaults always stay safe.
type Option func(*svgConfig)

// Size sets the square width/height in pixels (default 24). The stroke weight
// is derived from the size unless StrokeWidth is also set (Nexa: 16px => 2,
// 20px => 1.75, 24px+ => 1.5).
func Size(n int) Option {
	return func(c *svgConfig) {
		if n > 0 {
			c.size = n
		}
	}
}

// StrokeWidth overrides the size-derived stroke width. Values <= 0 are ignored.
func StrokeWidth(width float64) Option {
	return func(c *svgConfig) {
		if width > 0 && width < 1e6 {
			c.strokeWidth = width
			c.strokeSet = true
		}
	}
}

// Class appends a class name after the mandatory "nexa-icon" class.
func Class(class string) Option {
	return func(c *svgConfig) {
		c.class = class
	}
}

// Label makes the icon meaningful: it renders role="img" with the given
// aria-label (attribute-escaped) instead of aria-hidden="true". Use it for
// icon-only buttons and standalone illustrations; omit it for decorative icons.
func Label(label string) Option {
	return func(c *svgConfig) {
		c.label = label
	}
}

// Title renders an accessible <title> element (role="img") instead of
// aria-hidden="true". Label and Title may be combined.
func Title(title string) Option {
	return func(c *svgConfig) {
		c.title = title
	}
}

// Anim tags the SVG with the animation contract shared by the Nexa packages:
// data-nexa-anim="<preset>" and data-nexa-trigger="<trigger>". Motion itself is
// CSS; the SVG carries no animation runtime.
func Anim(preset string) Option {
	return func(c *svgConfig) {
		c.anim = preset
	}
}

// Trigger overrides the semantic data-nexa-trigger when Anim is set (defaults to
// the icon's own trigger, e.g. "hover"; accepts "manual", "press", "inview",
// "focus", "always", ...).
func Trigger(trigger string) Option {
	return func(c *svgConfig) {
		c.trigger = trigger
	}
}

// Active marks an animated icon as active (data-nexa-active="true"). Like the JS
// package, the attribute is only emitted together with an animation preset.
func Active(active bool) Option {
	return func(c *svgConfig) {
		c.active = active
	}
}

// SVG renders the icon as a standalone, XML-parseable <svg> string:
//
//	<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"
//	     viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"
//	     stroke-linecap="round" stroke-linejoin="round" class="nexa-icon"
//	     aria-hidden="true" focusable="false" data-nexa-icon="bell">…</svg>
//
// The attribute set, order and values match js/index.mjs svg(). All dynamic
// values are escaped. Decorative by default (aria-hidden); pass Label and/or
// Title to expose the icon to assistive tech.
func (i Icon) SVG(opts ...Option) string {
	cfg := defaultSVGConfig()
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}

	stroke := cfg.strokeWidth
	if !cfg.strokeSet {
		stroke = strokeForSize(cfg.size)
	}
	trigger := cfg.trigger
	if trigger == "" {
		trigger = i.Trigger
	}
	labelled := cfg.label != "" || cfg.title != ""
	className := "nexa-icon"
	if cfg.class != "" {
		className += " " + cfg.class
	}

	var b strings.Builder
	b.Grow(len(i.Inner) + len(cfg.title) + 384)
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="`)
	b.WriteString(strconv.Itoa(cfg.size))
	b.WriteString(`" height="`)
	b.WriteString(strconv.Itoa(cfg.size))
	b.WriteString(`" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="`)
	b.WriteString(formatNumber(stroke))
	b.WriteString(`" stroke-linecap="round" stroke-linejoin="round" class="`)
	b.WriteString(escapeAttr(className))
	b.WriteString(`"`)

	if labelled {
		b.WriteString(` role="img"`)
		if cfg.label != "" {
			b.WriteString(` aria-label="`)
			b.WriteString(escapeAttr(cfg.label))
			b.WriteString(`"`)
		}
	} else {
		b.WriteString(` aria-hidden="true"`)
	}

	b.WriteString(` focusable="false" data-nexa-icon="`)
	b.WriteString(escapeAttr(i.Kebab))
	b.WriteString(`"`)

	if cfg.anim != "" {
		b.WriteString(` data-nexa-anim="`)
		b.WriteString(escapeAttr(cfg.anim))
		b.WriteString(`" data-nexa-trigger="`)
		b.WriteString(escapeAttr(trigger))
		b.WriteString(`"`)
		if cfg.active {
			b.WriteString(` data-nexa-active="true"`)
		}
	}

	b.WriteString(`>`)
	if cfg.title != "" {
		b.WriteString(`<title>`)
		b.WriteString(escapeAttr(cfg.title))
		b.WriteString(`</title>`)
	}
	b.WriteString(i.Inner)
	b.WriteString(`</svg>`)
	return b.String()
}

// ---------------------------------------------------------------------------
// Swap / morph pairs and renderer.
//
// data/swaps.json declares 26 semantic click-swap pairs ([from, to, mode]).
// Reverse edges are implied unless the reverse source already owns a pair, so
// the generated table holds 49 directed edges — the same edges, in the same
// order, as the JavaScript and React packages. Motion is CSS-only; the markup
// just carries data-mode and data-nexa-active.
// ---------------------------------------------------------------------------

// swapModes is the closed set of transition modes understood by the shared
// animations.css (mirror|flip|rotate|slide|fade).
var swapModes = map[string]bool{
	"mirror": true,
	"flip":   true,
	"rotate": true,
	"slide":  true,
	"fade":   true,
}

// SwapPair is one directed edge of the semantic swap table: the canonical
// source icon, its counterpart, and the CSS transition mode.
type SwapPair struct {
	From string
	To   string
	Mode string
}

// pairBySource indexes the generated swap table by canonical source name.
var pairBySource = func() map[string]SwapPair {
	pairs := make(map[string]SwapPair, len(generatedSwapPairs))
	for _, pair := range generatedSwapPairs {
		pairs[pair.From] = pair
	}
	return pairs
}()

// Pair returns the semantic counterpart for name (e.g. Pair("ArrowLeft") ->
// {ArrowLeft ArrowRight mirror}). The lookup is case-insensitive, alias/kebab
// aware, and strips separators like Get. Unknown or pair-less icons return false.
func Pair(name string) (SwapPair, bool) {
	canonical, ok := lookupCanonical(name)
	if !ok {
		return SwapPair{}, false
	}
	pair, ok := pairBySource[canonical]
	return pair, ok
}

// Pairs returns every directed swap pair (49 edges: 26 declared plus implied
// reverses) in data/swaps.json expansion order, including the source icon, the
// same [from, to, mode] table as JS SWAP_PAIRS. The result is a fresh slice on
// every call.
func Pairs() []SwapPair {
	pairs := make([]SwapPair, len(generatedSwapPairs))
	copy(pairs, generatedSwapPairs)
	return pairs
}

// SwapMode returns the transition mode for name's semantic pair, falling back
// to "fade" when the icon is unknown or has no pair.
func SwapMode(name string) string {
	if pair, ok := Pair(name); ok {
		return pair.Mode
	}
	return "fade"
}

// swapConfig is the resolved option state for one swap render.
type swapConfig struct {
	active      bool
	duration    int
	mode        string
	label       string
	class       string
	size        int
	strokeWidth float64
	strokeSet   bool
}

func defaultSwapConfig() swapConfig {
	return swapConfig{duration: 260, size: 24}
}

// SwapOption customises SwapSVG. Options are applied in order.
type SwapOption func(*swapConfig)

// SwapActive sets data-nexa-active ("true"/"false", default false). A click
// handler flips this string attribute; the CSS transition does the rest.
func SwapActive(active bool) SwapOption {
	return func(c *swapConfig) {
		c.active = active
	}
}

// SwapDuration sets the transition duration in milliseconds (default 260).
// Negative values are ignored.
func SwapDuration(ms int) SwapOption {
	return func(c *swapConfig) {
		if ms >= 0 {
			c.duration = ms
		}
	}
}

// SwapTransition overrides the transition mode (mirror|flip|rotate|slide|fade).
// The default "" (or "auto") resolves the pair's semantic mode from the
// generated table. Explicit values are passed through, matching the JS/React
// contracts.
//
// It is named SwapTransition, not SwapMode, because SwapMode is the pair-mode
// query (SwapMode("Sun") == "rotate").
func SwapTransition(mode string) SwapOption {
	return func(c *swapConfig) {
		c.mode = mode
	}
}

// SwapLabel gives the swap group an accessible name: role="img" and
// aria-label are set on the wrapper; without it the wrapper is aria-hidden.
// The two inner icon SVGs are always decorative.
func SwapLabel(label string) SwapOption {
	return func(c *swapConfig) {
		c.label = label
	}
}

// SwapClass appends a class to the wrapper ("nexa-swap <class>").
func SwapClass(class string) SwapOption {
	return func(c *swapConfig) {
		c.class = class
	}
}

// SwapSize sets the square size of both inner icons (default 24).
func SwapSize(n int) SwapOption {
	return func(c *swapConfig) {
		if n > 0 {
			c.size = n
		}
	}
}

// SwapStrokeWidth sets the stroke width of both inner icons. When unset, the
// Nexa size table is applied automatically (16 => 2, 20 => 1.75, 24+ => 1.5),
// matching the JavaScript and React swap renderers.
func SwapStrokeWidth(width float64) SwapOption {
	return func(c *swapConfig) {
		if width > 0 && width < 1e6 {
			c.strokeWidth = width
			c.strokeSet = true
		}
	}
}

// SwapSVG renders a two-layer swap/morph widget matching the JavaScript and
// React markup contract exactly:
//
//	<span class="nexa-swap" data-mode="mirror" data-nexa-active="false"
//	      style="--nexa-swap-dur:260ms" aria-hidden="true">
//	  <span class="nexa-swap__a" aria-hidden="true"><svg …/></span>
//	  <span class="nexa-swap__b" aria-hidden="true"><svg …/></span>
//	</span>
//
// Flip data-nexa-active (e.g. from a click handler) to animate. The mode comes
// from the semantic pair table by default; override it with SwapTransition. Both
// icons accept aliases, kebab-case names and are case-insensitive. An unknown
// from or to returns "" (use Get first if the name is dynamic).
func SwapSVG(from, to string, opts ...SwapOption) string {
	fromIcon, ok := Get(from)
	if !ok {
		return ""
	}
	toIcon, ok := Get(to)
	if !ok {
		return ""
	}

	cfg := defaultSwapConfig()
	for _, opt := range opts {
		if opt != nil {
			opt(&cfg)
		}
	}

	mode := cfg.mode
	if mode == "" || strings.EqualFold(mode, "auto") {
		mode = SwapMode(fromIcon.Name)
	}

	iconOptions := func() []Option {
		options := []Option{Size(cfg.size)}
		if cfg.strokeSet {
			options = append(options, StrokeWidth(cfg.strokeWidth))
		}
		return options
	}
	a := fromIcon.SVG(iconOptions()...)
	b := toIcon.SVG(iconOptions()...)

	var out strings.Builder
	out.Grow(len(a) + len(b) + 480)
	out.WriteString(`<span class="nexa-swap`)
	if cfg.class != "" {
		out.WriteString(` `)
		out.WriteString(escapeAttr(cfg.class))
	}
	out.WriteString(`" data-mode="`)
	out.WriteString(escapeAttr(mode))
	out.WriteString(`" data-nexa-active="`)
	if cfg.active {
		out.WriteString(`true`)
	} else {
		out.WriteString(`false`)
	}
	out.WriteString(`" style="--nexa-swap-dur:`)
	out.WriteString(strconv.Itoa(cfg.duration))
	out.WriteString(`ms"`)

	if cfg.label != "" {
		out.WriteString(` role="img" aria-label="`)
		out.WriteString(escapeAttr(cfg.label))
		out.WriteString(`"`)
	} else {
		out.WriteString(` aria-hidden="true"`)
	}

	out.WriteString(`><span class="nexa-swap__a" aria-hidden="true">`)
	out.WriteString(a)
	out.WriteString(`</span><span class="nexa-swap__b" aria-hidden="true">`)
	out.WriteString(b)
	out.WriteString(`</span></span>`)
	return out.String()
}

// ---------------------------------------------------------------------------
// Categories (data/categories.json, mapped to canonical display names)
// ---------------------------------------------------------------------------

// Category is a curated group of icons, e.g. "communication" or "finance".
type Category struct {
	ID          string
	Label       string
	Description string
	Icons       []Icon
}

var categoryIndex = func() struct {
	byID    map[string]Category
	ordered []Category
} {
	byID := make(map[string]Category, len(generatedCategories))
	ordered := make([]Category, 0, len(generatedCategories))
	for _, entry := range generatedCategories {
		category := Category{ID: entry.ID, Label: entry.Label, Description: entry.Description}
		category.Icons = make([]Icon, 0, len(entry.Icons))
		for _, name := range entry.Icons {
			if icon, ok := Get(name); ok {
				category.Icons = append(category.Icons, icon)
			}
		}
		byID[entry.ID] = category
		ordered = append(ordered, category)
	}
	return struct {
		byID    map[string]Category
		ordered []Category
	}{byID, ordered}
}()

// Categories returns every category in catalog order.
func Categories() []Category {
	return append([]Category(nil), categoryIndex.ordered...)
}

// ByCategory returns one category by id (kebab-case, e.g. "communication").
func ByCategory(id string) (Category, bool) {
	category, ok := categoryIndex.byID[compactKey(id)]
	if !ok {
		category, ok = categoryIndex.byID[id]
	}
	return category, ok
}
